lines = student_code.split('\n')

# Check Task 1: import
has_import = any('import requests' in line for line in lines)
if not has_import:
    raise AssertionError('Task 1: Missing "import requests"')

# Check Task 2: r_success with GET and correct URL
has_r_success = False
for line in lines:
    if 'r_success' in line and 'requests.get' in line and '200' in line:
        has_r_success = True
        break
if not has_r_success:
    raise AssertionError('Task 2: r_success should use requests.get() with status/200 URL')

# Check Task 3: r_fail with GET and correct URL
has_r_fail = False
for line in lines:
    if 'r_fail' in line and 'requests.get' in line and '404' in line:
        has_r_fail = True
        break
if not has_r_fail:
    raise AssertionError('Task 3: r_fail should use requests.get() with status/404 URL')

