for line in lines:
    if 'post_success' in line and 'requests.post' in line and 'post' in line and 'json=' in line:
        has_post_success = True
        break
if not has_post_success:
    raise AssertionError('Task 4: post_success should use requests.post() with JSON and /post URL')

# Check Task 5: post_fail with POST, JSON, and correct URL
has_post_fail = False
for line in lines:
    if 'post_fail' in line and 'requests.post' in line and '405' in line and 'json=' in line:
        has_post_fail = True
